{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C33"],
      "claim": "Vinorelbine, a large complex alkaloid with high molecular weight and ring count, has absolute oral bioavailability of 43% in patients, directly supporting that complex large molecules can exceed the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C39"],
      "claim": "Rifapentine, a large lipophilic macrocyclic antibiotic, has absolute oral bioavailability of 70% in healthy volunteers, showing that high molecular weight and lipophilicity do not preclude high oral bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C55"],
      "claim": "Minocycline has approximately 90% oral bioavailability in humans, demonstrating that polycyclic, moderately lipophilic molecules can be very well absorbed orally.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C19"],
      "claim": "Ofloxacin has greater than 95% absolute oral bioavailability in healthy subjects, supporting high oral bioavailability for a molecule with multiple polar functionalities.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C26"],
      "claim": "Ondansetron has about 60% oral bioavailability in humans, supporting high oral bioavailability for a moderately sized heterocyclic drug.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C70"],
      "claim": "Encainide has a mean oral bioavailability of 42% in patients, supporting high oral bioavailability despite substantial first-pass metabolism.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C50"],
      "claim": "Meperidine has approximately 45% oral bioavailability in humans, supporting high oral bioavailability for a lipophilic basic drug.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C16"],
      "claim": "Ketanserin has absolute oral bioavailability of about 47% in healthy subjects, supporting high oral bioavailability for a lipophilic aromatic drug.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All high-transfer experimental analogues report oral bioavailability above 20%, many from direct absolute bioavailability comparisons versus IV. The physicochemical prior of low bioavailability is overridden by this consistent, transferable experimental evidence.",
  "evidence_gaps": [
    "No direct experimental pharmacokinetic data are available for the query molecule itself.",
    "No exact structural analogue with the same fused polycyclic scaffold was present in the evidence set.",
    "First-pass metabolism and solubility of the query molecule were not directly measured."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

